// π
package main

type Box struct{}
func (Box) Map[T any](x T) T { return x }
func After() int { return 7 }
func main() { if (Box{}).Map(17) != 17 { panic("wrong") }; if After()!=7 {panic("sibling lost")}; println("oracle:ok") }

